SELECT stddev(emar.value) AS standard_deviation FROM emar JOIN patients ON emar.subject_id = patients.subject_id JOIN icustays ON emar.subject_id = icustays.subject_id WHERE patients.gender = 'M' AND patients.anchor_age = 90 AND icustays.first_careunit = 'ICU' AND patients.anchor_year BETWEEN 85 AND 95 AND emar.event_txt = 'Mean Arterial Pressure' AND emar.charttime BETWEEN icustays.intime AND (icustays.intime + interval '24 hours');